import {noteContinuityGuideSections} from './note-continuity.mjs';
import {audiencePages} from './audience-pages.mjs';

// Public explanations only. These records confer no financial authority and
// contain no account reads, mutable prices or invented qualification results.
const page=(slug,group,title,description,intro,visual,sections,related,extra={})=>({slug,group,title,description,intro,visual,sections,related,...extra});
export const learningPages=[
...audiencePages,
page('your-account','Banking','Your account','Understand your available balance, saved observations and received Notes in one account.','One balance. A clear view of what you can use.','funding',[
 ['A familiar starting point','Your account brings available money and its history into one place. Send an amount, receive a payment or create a Note without choosing a funding rail. The application selects available Reserve first, then Settlement for the remainder. The transaction proof preserves the exact composition underneath.'],
 ['Available and received','A confirmed account balance and a Note received offline are different states. Received Notes retain the complete original proof on your device. Their deposits reconcile when connected before a payment or a new Note uses that value. The interface identifies received value without counting an unconfirmed deposit twice.'],
 ['A balance with a moment','Your balance is shown with the time it was read. A retained observation can appear immediately when you reopen the account; the latest supported account read follows in the background. A saved display remains an observation of that moment, rather than a new authorization to spend.'],
 ['Optional depth','Balance details explain Reserve, Settlement and the source moment. Reserve records proof-backed funds. Settlement records proof-native value in exact Phi units; its dollar presentation follows the supported conversion. Both belong to the same account and are counted once.'],
 ['History you can inspect','Open an activity record to see its amount, participants, moment and carried source. For an asset transfer, compare its supported transfer-time valuation with its current value. A change in valuation is distinct from money entering or leaving the account.'],
 ['Keep your authority','Save your original Identity Record and important proofs. An account backup restores identity access; it does not clone protected offline Note custody or reconstruct every private local file. Resolve unfinished operations before clearing device storage.']
],['/learn/payments/','/learn/reserve-and-settlement/','/learn/receiz-id/']),
page('payments','Banking','Payments','Send and receive through Receiz ID with an exact review, a signed operation and a connected receipt.','Choose who. Choose how much. Keep the receipt.','journey',[
 ['Find the recipient','Use a Receiz username, a payment request or a receiving link. Suggestions can include existing conversations and matching public profiles. A display name helps discovery; the resolved account identity determines the payment destination. Review that destination before approval.'],
 ['One amount','Enter the amount you want to send. Funding uses available Reserve first and Settlement for any remainder. You do not need to choose between them. When both contribute, the receipt retains both components and their exact source basis.'],
 ['Review before approval','Account access does not authorize a payment. The review identifies the recipient, amount and supported execution. Your device signs the exact action. A link, QR code, conversation or assistant suggestion cannot substitute for your approval.'],
 ['One financial result','An operation can carry several records: the money movement, delegated authorization and its proof. Related evidence belongs inside the payment view. Separate evidence records do not mean the account was debited twice. The financial result is checked against its signed operation.'],
 ['Recover an interrupted payment','A missing response does not establish failure. The application retains the exact attempted operation and checks its result before retrying. Do not create a different payment merely because a confirmation was interrupted. This preserves once-only execution across uncertain responses.'],
 ['Follow the value','The receipt connects the event to available funding evidence. Object-level FIFO attribution is explicitly calculated from the recorded source basis and spend order. It explains which sources support a spend without claiming the original pooled transfer recorded an individual object allocation.']
],['/learn/get-paid/','/learn/payment-requests/','/learn/receipts/','/learn/source-of-funds/']),
page('get-paid','Banking','Get paid','Share a payment link, add a website button or install the existing Receiz checkout. Start in Receive and keep the same receiving account.','A link. A button. Money to your account.','journey',[
 ['Start in Receive','Your account already has a public receiving address. Share its Bankeiz payment link in a message, on an invoice or wherever you can publish a link. Add an optional amount when you want to request a specific payment. Opening the link prepares the destination. The customer can use their balance, add money by card or choose Pay with a Note, then review and approve the payment in their own account.'],
 ['Put a button on your website','Open Accept payments anywhere in Receive and copy Payment button. Paste it into your website builder’s custom HTML block. The button opens the same Bankeiz request, with your confirmed username and optional amount. If your website only accepts links, attach your payment link to its own button instead. No secret key belongs in a public button.'],
 ['Keep card checkout on your site','Choose Embedded checkout to copy the existing Receiz widget. Paste it into a custom HTML block that permits scripts. Customers enter an amount and complete the supported card checkout within the site. Receive also supplies your Receiz checkout link for places that cannot run a widget. The current widget lets the customer choose an amount; it does not inherit the optional amount in your Bankeiz request. Your Receiz profile must be public for this checkout.'],
 ['Receive an original Note','Your Bankeiz payment button supports Reserve, Settlement and Settlement Reserve Notes through one Pay with a Note option. The payer deposits a valid Note they own, its credit reconciles through Receiz, and the ordinary account payment pays the merchant. The complete source chain and funding composition remain intact. This requires a confirmed deposit before spending; a copied image or a Note addressed to someone else cannot pay an order. Receiz’s separate embedded widget retains its legacy Wallet Note compatibility path.'],
 ['Build into your application','Use the pinned Receiz SDK for a custom checkout, with the merchant, price and order reference selected by your trusted application. Reuse the existing checkout host and account operations instead of creating a second balance or payment ledger. The integration reference provides a typed example, exact response checks, recovery guidance and the boundaries of Notes, account payments and commerce capabilities.'],
 ['Confirm before delivery','A button click, a checkout session, a browser message or a success URL is not payment confirmation. Check the original session with Receiz from your trusted application, match the intended merchant, exact amount and confirmed account credit, then record fulfillment once. Keep an interrupted session reference and inspect it before asking the customer to pay again.'],
 ['One receiving account','Use the same identity for customer payments, your own payments and their connected history. A website integration changes where the customer starts; it does not create another account for the merchant. Card availability, limits and website permissions follow their existing host and processor rules. Keep the customer’s approval and the actual payment result explicit.']
],['/learn/payment-requests/','/learn/notes/','/developers/'],{resources:[['Payment integration reference and examples','https://github.com/kojibai/reality-grade-banking/blob/main/institution/accept-payments.md']]}),
page('payment-requests','Banking','Payment requests','Understand receiving links, QR codes and recipient selection before any payment is authorized.','A clear destination. A deliberate payment.','journey',[
 ['Share where to pay','Receive offers your username and a link that opens a payment addressed to your account. Copy or share it through the available device controls. The destination is resolved through Receiz; a familiar username is a convenient address, not the signing authority.'],
 ['Opening is not paying','Opening a receiving link prepares a payment. It does not transfer money. The sender still checks the recipient and amount and authorizes the action with their own identity. A request can describe an intent without granting access to either account.'],
 ['Links and QR codes','A QR code or programmed NFC link is another way to carry a request. Check the resolved destination rather than trusting an image or surrounding text. A tampered request must not silently change the recipient of a signed payment.'],
 ['An amount, when provided','A request may include an amount or leave it for the sender. The final review is authoritative for the action being approved. Changing a requested amount means reviewing that new amount before signing; the visual appearance of the request cannot expand consent.'],
 ['Share the result separately','A receiving link asks for payment. A transaction receipt records an event and its supported result. Share the receipt when someone needs the actual evidence, including its moment, amount and source context. Keep private identity material out of either link.']
],['/learn/payments/','/learn/receiz-id/','/learn/receipts/']),
page('deposits','Banking','Deposits','Bring money and assets into one account, fund what comes next and keep the proof of where value came from.','Send money. Back what you create. Keep the proof.','journey',[
 ['Put your value to work','Use confirmed funds to pay someone, create a Note or back an asset or currency. Keep ownership and source history connected as value moves. One account gives you familiar money and the evidence behind it.'],
 ['Choose what you are adding','Deposit supports different incoming sources. Funding the account, depositing a completed Note, retaining an original proof and requesting physical asset intake establish different facts. The account admits the result appropriate to that source; selecting an option does not create funds.'],
 ['Card funding','Use the supported checkout to fund the account by card. The card flow has its own review and processor result. A completed checkout screen alone is not a substitute for the verified funding result that makes money available. Pending operations retain their references for recovery.'],
 ['Deposit an original Note','Open the original Note image or supported source. The reader checks its carried proof and recipient binding. A completed account-destination Note can be received and retained offline. Connection reconciles the exact deposit and confirms once-only credit before that amount can be spent from the account.'],
 ['Keep the original','A screenshot or converted image may remove the proof embedded in the original. Preserve the received file intact. Displayed artwork, a denomination or a successful upload is not itself evidence of an issued Note, ownership or account credit.'],
 ['Physical items','Physical intake needs a verifiable item, custody evidence and a defined transferable claim. An intake request records a request. Admitted custody and ownership require their corresponding proofs and supported execution; neither follows automatically from a description or photograph.'],
 ['After confirmation','The confirmed result belongs to account history with its source and moment. If a response is lost, resume the saved operation instead of funding again. This is how incoming value remains connected to its origin without counting the same event twice.']
],['/learn/notes/','/learn/physical-assets/','/learn/your-account/']),
page('notes','Banking','Notes','Create, carry, receive and deposit Reserve, Settlement and Settlement Reserve Notes with complete proof continuity.','Your money. Ready to carry.','notes',[
 ['Choose an amount','Create a Note from your account by entering one amount. Your account supplies Reserve first and Settlement only for any remainder. There is no funding selector. Creation moves the approved amount into the Note only when issuance completes; a preview has no spendable value.'],
 ['Three titles. One experience.','A Reserve Note carries proof-backed value. A Settlement Note carries proof-native value. When both contribute, a Settlement Reserve Note carries Proof-backed Native value. The original proof retains the exact split. Reserve dollars stay fixed; Settlement retains its exact Phi units and its dollar value follows the deterministic rate.'],
 ['Send the addressed original','Ask the recipient for a receiving request. The resulting handover binds the original source to that recipient. Save and share the updated Note, rather than an earlier preview. A picture alone cannot change the destination, establish ownership or create another account credit.'],
 ...noteContinuityGuideSections,
 ['Keep a recoverable result','Retain the original Note, its receiving proof and any unfinished attempt. If issuance or deposit loses its response, resume that same operation. Do not discard an unknown funded result or clear device state to force a new attempt.'],
 ['The qualification boundary','Connected creation uses Receiz’s once-only connected authorization and does not require a custody conformance Face ID prompt. Receiving and retaining a completed account-destination Note also requires no custody enrollment. Creating new spend authority fully offline requires conforming protected state and prepared resources. A device check is an optional diagnostic, not a payment or universal certification.']
],['/learn/deposits/','/learn/reserve-and-settlement/','/conformance/#note-continuity']),
page('messages','Banking','Messages and your assistant','Your conversations, memories and next steps in one account. Understand a payment, revisit your history and prepare what comes next.','Your conversations. In the same account.','journey',[
 ['The conversations you already have','Messages reuses Receiz’s existing direct and group conversations under your open identity. It does not create a separate Bankeiz social account. Retained encrypted inbox data can appear on reopening while the existing connection synchronizes in the background.'],
 ['Find someone new','Search by name or username to find Receiz profiles beyond your current inbox. Select the intended person before starting a conversation. A public profile match is discovery information; the actual conversation uses its resolved participant identities.'],
 ['A natural exchange','Your outgoing message appears immediately with its delivery state. Typing indicators use the existing Receiz channel rather than a separate polling service. A pending local bubble is not presented as a confirmed remote delivery. Replies and call state come from the existing communication capabilities.'],
 ['An assistant with continuity','Understand a payment, revisit a memory and prepare your next move in a conversation that can carry forward. Your assistant uses the existing Receiz Twin and the memories and records you choose to share; it does not receive every private account record automatically. With access, Your assistant opens first. Otherwise Messages opens first, and you can ask a question in the same familiar assistant view to explore the upgrade.'],
 ['Actions stay deliberate','Questions can use selected records as context. Sending a message, placing a call and approving a payment remain distinct actions. An assistant response does not grant financial authority. Calling uses device microphone or camera permission when those capabilities are requested.'],
 ['Upgrade the same profile','The supported subscription checkout upgrades your Receiz profile, rather than creating another subscription identity. Card checkout uses the existing Receiz purchase flow. A pending checkout or local success display is not treated as a verified entitlement until the underlying result confirms it.']
],['/learn/payments/','/learn/account-access/','/learn/receiz-id/']),
page('receiz-id','Banking','Receiz ID and Identity Records','Open your existing identity, receive through a username and protect the original Identity Record that holds your authority.','One identity. Your account and its continuity.','identity',[
 ['Open or create','Enter creates a Receiz identity. Use existing account opens the original Identity Record you provide. The source is inspected on your device. A protected legacy record asks for its original unlock phrase; new self-contained records do not require a separately generated recovery phrase.'],
 ['Names and authority','Your username makes you easy to find and pay. The account identity and its signing key establish authority. A public profile image or username is not permission to act as the account. Receive displays the familiar username while the payment flow resolves its actual recipient.'],
 ['The same account access','Opening your ID gives the approved account access, including supported Receiz messaging. Financial actions still have their own exact review and authorization. You do not create a separate identity for conversations, asset ownership or account history.'],
 ['Back up the original','Use Back up my Identity Record and keep the downloaded original private. A screenshot, edited image or renamed file is not a substitute for its structured source. If the original requires a phrase, preserve that phrase separately. Never publish a private Identity Record on your Showcase.'],
 ['History is carried evidence','An Identity Record can carry verified account summaries and available history, but it need not contain every private transaction. Retained receipts and original assets add their own evidence. Reopening an identity is not the same as reconstructing every local record or restoring device-qualified Note custody.'],
 ['Before removing a device','Resolve held Notes and unfinished requests before removing your ID or clearing storage. Removing the ID stops that browser’s open access; it does not revoke other copies of the Record or erase public records. Protect the device and every private original that can open the identity.']
],['/learn/signing-key/','/learn/account-access/','/learn/payment-requests/']),
page('proof-objects','Assets','Proof objects and ownership','Inspect the source, authorship, ownership, rights and history carried by a sealed asset.','An asset with its evidence attached.','asset',[
 ['Start with the original','A proof object carries structured evidence in its original source. The reader can check integrity and the assertions actually covered by its signatures and proofs. Keep the original bytes: an appearance, a title or a link alone cannot establish the same result.'],
 ['What the object connects','An object can connect an authored moment, its claim, media, ownership and carried transitions. A verifier evaluates the applicable format and evidence. A valid seal establishes the integrity of a recorded claim; external truth, physical custody and legal rights require their own supporting basis.'],
 ['Create and publish','Define the moment and what it claims, attach suitable media or optional long-form text, then seal it under your identity. The canonical publication flow places the publicly admitted object on your Receiz Showcase and makes it available to the public collection. An interrupted publication retains its exact recovery state.'],
 ['Discovery and ownership','A public listing lets others discover an object and inspect its current supported presentation. Listing is not ownership authority. A transfer requires the current source, the authorized owner and the supported handover rules. A saved listing cannot replace that proof.'],
 ['Value and backing','A deterministic valuation describes a value under a stated method. It does not independently establish sale proceeds or cash held against the object. Backing, redeemability, share rights and custody are separate claims that must be supported by their corresponding originals.'],
 ['Continuity after a change','Ownership changes and supported financial events retain their source relationships. Receipts connect the new event to its predecessors. This allows a later reader to inspect the object’s actual history instead of relying only on the current screen or the operator’s description.']
],['/learn/creating-an-asset/','/learn/ownership/','/learn/asset-rights-and-backing/']),
page('creating-an-asset','Assets','Create an asset','Seal a moment, define its claim and publish the admitted original to your Receiz Showcase and the public Market.','Seal a moment. Make its claim explicit.','asset',[
 ['Define the moment','Begin with a specific moment and a clear claim: what is being recorded, who authored it and what someone should understand from it. Use a meaningful title. A precise claim is more useful than a broad label because a future reader can tell what the source actually asserts.'],
 ['Choose the appropriate expression','Attach images, video, audio, a document or another supported media type. Add long-form text when the claim needs depth. The form adapts to the media rather than asking for unrelated fields. The original media and its classified content determine how it can be discovered.'],
 ['Make rights explicit','Authorship, access, ownership, licenses, units and backing are different statements. Describe only rights you can establish. Referencing a held proof does not automatically commit it as collateral. An asset definition cannot create physical custody, account funds or legal title by itself.'],
 ['Seal the source','Review the final source and publish through the supported Receiz operation. The identity signs the actual publication. The admitted original remains the authority for its contents; the form, preview and local draft are preparation states.'],
 ['Showcase and Market','Successful canonical publication connects the public object to your Receiz Showcase and the public discovery collection. Music, images, videos, books, essays, moments, collectibles and documents use the content classification already carried by the source. Cards belong to Collectibles.'],
 ['Resume without duplicating','If upload or publication is interrupted, retain and resume the saved attempt. A local seal without confirmed publication is not presented as a completed public listing. The recovery path checks the existing result before creating another public event.']
],['/explore/','/learn/proof-objects/','/learn/asset-rights-and-backing/']),
page('ownership','Assets','Ownership','Understand current ownership authority, recipient-bound handovers and the history preserved by an asset transfer.','Ownership moves. Its history stays connected.','ownership',[
 ['Current authority','A title or public username identifies an asset for discovery. Current ownership is established by the applicable source and its admitted transitions. An earlier owner’s valid historical proof does not automatically authorize a new transfer after ownership has moved.'],
 ['A specific handover','The authorized operation binds the object, predecessor and intended recipient. Changing those fields changes the action that must be verified. The resulting proof records the supported change rather than relying on an informal message or an updated profile label.'],
 ['What the recipient keeps','The recipient retains the original and its carried history. The reader can inspect the previous source, authorized transition and new owner. Media access and a transferable right may have different scopes; the object’s actual terms determine what was conveyed.'],
 ['Value at the moment','Where supported inputs exist, the Ledger reconstructs a card or other supported object’s value at its transfer pulse and shows its current valuation separately. That comparison is a valuation change, not evidence of a sale price or payment unless a financial record establishes one.'],
 ['Avoid competing claims','Replay and stale predecessors must be rejected under the relevant execution rules. Connected execution and qualified protected offline custody establish exclusivity through different mechanisms. An ordinary timestamp or duplicate file cannot replace either mechanism.']
],['/learn/fractional-ownership/','/learn/receipts/','/learn/security/']),
page('fractional-ownership','Assets','Fractional ownership','Inspect share units, supply, custody claims and the exact scope of a fractional ownership position.','A defined share. An inspectable whole.','ownership',[
 ['Define what a share represents','A fractional position needs a specific underlying claim, unit definition and supply. Owning a number of units does not by itself establish access, redemption, income or legal title. Those rights must be explicit in the source and supported by the relevant evidence.'],
 ['Count exact units','Unit amounts and total supply follow exact rules. A display percentage is a presentation of that ratio. Transfers and supported issuance must preserve supply and prevent the same units from being assigned twice; rounding in a screen cannot authorize additional ownership.'],
 ['Connect to custody','For a physical item, the asset receipt and custodian establish the backing relationship. For a digital claim, inspect its corresponding rights and original. Share supply, backing and owner transitions need to remain linked rather than becoming unrelated labels.'],
 ['Review supported execution','A share definition alone does not guarantee that purchase, division or redemption is executable in every deployment. The available action must identify its admitted contract, current proof and authorization. Do not infer a live market from the existence of a share count.'],
 ['Inspect the result','Keep the source that records the actual share position and any related payment. A valuation of the whole is different from the executable price of a share. Liquidity, proceeds and redemption availability require their own evidence.']
],['/learn/ownership/','/learn/physical-assets/','/learn/asset-rights-and-backing/']),
page('physical-assets','Assets','Physical assets','Connect a physical item to its custodian, admitted receipt and defined transferable ownership claim.','The item. Its custody. Your evidence.','asset',[
 ['Identify the item','A physical asset needs a description precise enough to distinguish the item being claimed. Photographs and serial details can support identification, but a picture alone cannot demonstrate possession, condition, authenticity or current custody.'],
 ['Record the custodian','The custody source must identify who holds the item, what was received and the admitted conditions. A deposit request is a request for intake. It must not be displayed as a completed custody receipt before the required evidence and admission exist.'],
 ['Define the transferable claim','Holding a receipt, owning a share and owning legal title can be different rights. State what can move, what can be redeemed and which obligations or restrictions apply. A digital transfer cannot silently expand the claim beyond what its source supports.'],
 ['Preserve the chain','Item evidence, custody receipt, ownership and any admitted units remain connected through their originals. A receiver should be able to follow each relationship and identify missing or unsupported claims. Verification must not substitute a current listing for the underlying custody proof.'],
 ['Separate valuation from realization','A calculated value is not a guaranteed cash redemption or buyer commitment. Realizing value depends on the actual transaction, rights and supported counterparties. Keep that distinction visible in institutional depth while ordinary account actions remain simple.']
],['/learn/deposits/','/learn/fractional-ownership/','/learn/asset-rights-and-backing/']),
page('asset-rights-and-backing','Assets','Rights and backing','Distinguish source integrity, authorship, ownership, licenses, physical custody, funding and enforceable rights.','Know exactly what the proof establishes.','verification',[
 ['Integrity','An integrity check establishes that the examined bytes match the relevant digest or verified source. It does not independently prove that every sentence in the source is true. The verification result needs to state the actual object, method and scope checked.'],
 ['Authorship and ownership','A signature can bind a statement to a signing identity under the applicable rules. Current ownership needs the admitted ownership chain. Authorship, present possession and transferable ownership are related only where the source explicitly and validly connects them.'],
 ['Rights','Access, copying, distribution, licensing and redemption are different permissions. Read the actual rights carried by the claim. A purchase cannot be assumed to include every possible right merely because an object is sealed or publicly listed.'],
 ['Backing','Backing requires a supported relationship to another asset, funded amount or custodian. An attached proof can provide evidence without being committed as backing. Funding conservation and current spend authority must be verified through the relevant financial operation.'],
 ['External effect','Legal recognition, insurance, physical delivery and institutional acceptance depend on evidence and applicable arrangements beyond a cryptographic seal. Conformance evaluates a stated technical capability. It is not a universal certification of truth, legal status or investment quality.'],
 ['A useful inspection','Ask what was claimed, who authorized it, what supports it, what changed and what remains outside the proof. The answer should link to originals rather than decorative trust labels. A clear boundary makes a source more useful to the next independent reader.']
],['/learn/proof-objects/','/learn/security/','/standards/']),
page('proof-native-economy','Markets','The proof-native economy','Follow value from an original asset through ownership, account funding, payments and independently inspectable history.','Your money. Your assets. Their proof.','economy',[
 ['Proof belongs with what you own','Know where value came from, who owns it and how it moved. Carry the history with the asset and keep the evidence with the payment. That is the practical benefit of the proof-native economy: familiar actions with a source you and the next participant can inspect.'],
 ['An economy begins with sources','An economic claim becomes more useful when its source, rights and history remain available to the next participant. Proof objects provide a structured way to carry that evidence. The economy connects those sources to supported ownership and financial operations under explicit rules.'],
 ['Assets and money','Assets record defined claims. Account value records what the supported financial model admits. Settlement represents proof-native value; Reserve records proof-backed funds. Everyday actions use one balance, while exact units and funding distinctions remain preserved in the original proofs.'],
 ['From value to an action','A valuation can be reconstructed from its admitted inputs and moment. A payment or purchase additionally needs current authority, funds and an executable operation. The displayed calculation does not by itself move money, establish liquidity or authorize another participant’s account.'],
 ['Continuity across participants','A recipient should be able to inspect where an object or payment came from, what was authorized and what result followed. Receipts and source-carried history retain these relationships. A calculated FIFO attribution explains the use of a pooled funding basis without rewriting the original event.'],
 ['A market that can be examined','The public collection makes admitted assets discoverable by their actual content. Global Market Cap aggregates the supported valuations of its stated universe. Sealing times, dated evidence, deterministic projections and the current valuation have different meanings and remain identified. It is not a measure of GDP, realized sales or cash backing.'],
 ['An open standard of evidence','Institutions can inspect the pinned schemas, implementation and reference checks. Conformance belongs to a specific capability, version and demonstrated result. A missing assessment is not a pass or an invented failure. The same evidence requirement applies to this reference implementation.'],
 ['A familiar experience with deeper records','People can send, receive, hold assets and carry Notes without studying the underlying rails. The depth remains available when an engineer, recipient or institution needs to reconstruct the action. Simplicity in the interface is supported by precise records underneath.']
],['/market-cap/','/learn/how-value-works/','/standards/']),
page('markets','Markets','Markets','Discover publicly listed assets, inspect ownership and understand the difference between a valuation and a completed trade.','Discover an asset. Examine its source.','market',[
 ['A public collection','Explore opens without signing in. It shows available public objects, their source-supported owners and current valuations. A public listing is discovery information; it does not disclose your private account or grant permission to transfer an asset.'],
 ['Categories that describe the content','Music, images, videos, books, essays, moments, collectibles and documents use existing media classification. Cards are collectibles. An object can match more than one meaningful content description; category counts should not be summed as a unique asset total.'],
 ['Inspect before acting','Open an asset to inspect its original source, claim, ownership, history and supported value chart. Publication, current ownership, backing and valuation are separate evidence questions. The detail view should let you follow the supporting source rather than merely read a label.'],
 ['A quote and a trade','The valuation method computes a supported value at a moment. It does not guarantee a buyer, sale proceeds or redemption. Available purchase or sale actions require their own exact review, authority and financial execution. A public observer cannot trade merely by opening the listing.'],
 ['History and current value','An asset enters the historical universe at its actual supported sealing or opening coordinate. Dated observations and deterministic projections retain their distinct roles. A current pricing snapshot must not be silently moved into earlier history.'],
 ['Keep the result','A completed trade retains the ownership and payment evidence appropriate to that operation. An interrupted request resumes against its existing result. Discovery and display can be immediate from retained data while consequential actions still verify current authority.']
],['/explore/','/market-cap/','/learn/ownership/']),
page('global-market-cap','Markets','Global Market Cap','Examine the public valuation universe, historical entry dates, current aggregate and exact boundaries of Global Market Cap.','One market view. Every included source accounted for.','market',[
 ['What the total measures','Global Market Cap is the sum of supported public asset valuations in the displayed universe at the selected moment. It is an aggregate valuation, not cash in accounts, reserve backing, realized trade proceeds, liquidity or economic output. The universe and calculation basis matter as much as the headline.'],
 ['When an asset enters','Each card or object belongs at its supported sealing or pack-opening coordinate. Its opening value is used at entry. A later price snapshot cannot be treated as its opening price or assigned to an unrelated calendar date. Undated changes cannot become fabricated historical observations.'],
 ['How the line develops','The existing model combines supported dated evidence with the admitted deterministic projection. Projection is a rule-based reconstruction, identified as such; it is not an archive of executed market trades. The live endpoint and the historical basis must use compatible units and avoid adding the same asset twice.'],
 ['Assets in circulation and assets listed','The count of circulating assets and the count discoverable in the public collection describe different sets. Not every circulating asset must have a public listing or a supported valuation in this view. Listing coverage is not evidence that an unlisted object is invalid or that a source failed.'],
 ['Current pulse, current inputs','Where complete deterministic pricing inputs are held, the existing local valuation updates with the Kai pulse. Refreshing public sources can update those inputs. The display must not replace an unavailable value with an invented zero or imply a retained input is newly fetched evidence.'],
 ['Inspect the calculation','Use the public Market to open individual sources, inspect current values and compare the temporal basis. The valuation guide exposes the existing math. This explanation introduces no second valuation engine and does not alter the accepted market curve.'],
 ['Interpreting movement','A change can reflect an asset entering the universe, supported changes in the inputs or deterministic time progression. It need not represent a deposit, trade or realized gain. Institutional reporting should state the universe, moment, method and evidence together.']
],['/explore/','/learn/how-value-works/','/learn/price-history/'],{path:'/market-cap/'}),
page('reserve-and-settlement','Markets','Settlement and Reserve','Understand the two preserved sources beneath one available balance and automatic Note funding.','One account. Complete funding continuity.','funding',[
 ['See the same shared balance','Your account brings Settlement and Reserve into one balance. Settlement is proof-native value; Reserve holds proof-backed funds. Both are counted once. Ordinary payments and Notes choose their funding automatically, preserving the source composition in their original proofs.'],
 ['Settlement and destination continuity','Settlement preserves exact Phi units with a source-supported dollar presentation. A receiving implementation must preserve the required ownership, value and history under the applicable continuity contract. A valuation and an available payment destination remain separate facts.'],
 ['Reserve','Reserve holds proof-backed funds with their admitted origin and current ownership. Funding becomes available through a verified result, rather than an unconfirmed checkout screen or an asserted deposit. Subsequent movements preserve the applicable source basis.'],
 ['How notes work','Choose one amount. Your account uses Reserve first and Settlement for any remainder. The funded original is a Reserve Note, Settlement Note or Settlement Reserve Note according to its actual funding. A combined Note carries Proof-backed Native value and preserves the exact split. Keep the original file intact.'],
 ...noteContinuityGuideSections,
 ['The receiving standard','Conformance is bound to a specific implementation, capability and evidence. Until assessed, a receiving capability is not demonstrated. A reproduced applicable failure is nonconforming for that scope until corrected and reassessed. A protocol report does not grant financial authority or legal recognition.'],
 ['Leaving proof-native rails','A supported legacy destination may not preserve source-carried continuity in its receiving balance. Your original outgoing receipt remains evidence of the supported event. Review the actual destination and execution before authorizing a movement.']
],['/learn/notes/','/learn/your-account/','/learn/source-of-funds/']),
page('circulation','Markets','Circulation and listings','Distinguish circulating assets, issued units, public listings and the subset with supported valuations.','A clear count starts with a defined universe.','market',[
 ['Assets in circulation','A circulation count refers to the admitted objects or units under a stated source and method. An asset object and its issued units are not interchangeable counts. Reports need to identify which they measure, their moment and the applicable state.'],
 ['Assets listed','A listing is a public discovery entry. It can expose a title, owner, media and supported valuation without granting transfer authority. The listed universe can be smaller than circulation because public discovery and economic existence are different properties.'],
 ['Supported valuations','Only objects with the necessary admitted inputs can contribute a supported valuation under the displayed method. A missing valuation is not automatically zero. It also does not establish that the object is worthless, funded, liquid or invalid.'],
 ['Avoid double counting','Different categories may overlap because a source can carry several media types. Ownership transfers do not issue another copy of the same economic object. Aggregations should preserve object identity, supply and entry time rather than counting every record or category occurrence as a new asset.'],
 ['Reading a total','Use circulation, listing and valuation counts for their own questions. A market total should identify its included universe and method. A gap between counts should be explained precisely, without a vague failure label that makes discovery coverage look like a broken proof.']
],['/market-cap/','/learn/markets/','/learn/fractional-ownership/']),
page('price-history','Markets','Value over time','Read opening values, dated records, deterministic projections and current asset valuations without confusing them with trade prices.','The right value. At the right moment.','valuation',[
 ['Start at the actual opening','A card enters its history at the supported pack-opening or sealing coordinate with its opening value. Objects must not all appear at the beginning of an unrelated chart range or at the date of a later pricing snapshot.'],
 ['Recorded evidence','A dated source supports a value at its stated moment under the applicable method. It cannot establish every intermediate market price. Undated snapshots remain undated; chart sampling must not turn missing observations into fictitious trades.'],
 ['Deterministic projection','Where the admitted valuation rules support reconstruction, the curve can be calculated at a chosen pulse from the held inputs. It is identified as a deterministic projection. This differs from interpolating invented trade history or smoothing a line to make it look more organic.'],
 ['At transfer and now','A transfer receipt can show an object’s reconstructed value at the exact transaction pulse and its current supported value. The difference and percentage use those two values, with direction indicated by a restrained arrow and color. A zero or unavailable starting basis cannot support an ordinary percentage comparison.'],
 ['What a gain means','A change in valuation is not automatically a realized return, cash payment or sale proceeds. Supply changes and entry into an aggregate universe have different effects from price movement. Keep the source, units and moment alongside the comparison.'],
 ['Enough history to compare','A time range needs meaningful supported history. A control that cannot produce a useful comparison should not imply that a complete series exists. The available chart and its method should explain what can actually be reconstructed.']
],['/learn/how-value-works/','/market-cap/','/learn/receipts/']),
page('receipts','History','Transaction receipts','Inspect participants, amount, moment, authorization, source evidence and the recorded result in a shared transaction receipt.','The event. Its source. Its result.','receipt',[
 ['A receipt records an event','A receipt connects a supported action to its participants, amount, moment and result. It is more useful when the original source remains available for independent reading. The appearance of a confirmation is not a substitute for that evidence.'],
 ['Read the amount in context','A payment records the actual transferred amount. An asset handover can also show the asset’s value at transfer and its current supported valuation. Those values answer different questions from a purchase price; a valuation should not be relabeled as money paid.'],
 ['Follow the source','Open the funding detail to inspect its carried causal basis. A single component does not need an unnecessary Reserve or Settlement heading. When both contribute, their separate amounts and source relationships remain visible within the same transaction.'],
 ['Related evidence belongs together','A delegated wallet transfer can record authorization for the associated payment. It belongs inside that payment’s expanded evidence rather than competing with it as an apparent second debit. Keep both valid originals while presenting one understandable financial event.'],
 ['Share a useful link','Use Share or Copy to send the supported receipt link. The public receipt presents the evidence available for that selected record. Review what it discloses before sharing. A receipt link must not contain a private Identity Record, usable signing key or unlock phrase.'],
 ['Retain independently','Save the original evidence when you need durable continuity. A link can help another reader find a record, but service availability is different from holding the source. Independent verification evaluates the original under its matching supported rules.']
],['/ledger/','/learn/source-of-funds/','/learn/memory-crystals/']),
page('source-of-funds','History','Source of funds','Follow funding events, proof objects and calculated FIFO attribution through the complete supported causal chain.','Trace the payment back to its source.','provenance',[
 ['Begin with the event','A payment receipt identifies the actual movement and its moment. The causal view follows the source relationships carried by the available proofs. It preserves original events and distinguishes supporting evidence from a second financial action.'],
 ['Reserve origins','Reserve can derive from admitted funding, prior transfers or supported deposits. Follow those predecessor records to their actual funding basis. A source description does not invent an underlying proof object when the origin is a processor funding event or another type of admitted source.'],
 ['Settlement proof basis','Settlement value is connected to its admitted proof basis. For pooled balances, the receipt can calculate object-level FIFO attribution: consume the oldest supported available source first, carry its remainder forward, then use the next source. One object may lawfully support several spends until its available amount is exhausted.'],
 ['Calculated means calculated','FIFO slices reconstruct attribution from the held basis and spend order. They are explicitly calculated, rather than presented as an allocation recorded by the original Wallet transfer. The distinction preserves the truth of both the original pooled operation and the more detailed explanatory reconstruction.'],
 ['Multiple sources, one payment','A transaction can use several proof objects or incoming funding events. The source view retains their individual relationships and applicable amounts. If both Reserve and Settlement contribute, the two funding components are shown together without obscuring their separate causal bases.'],
 ['Boundaries stay visible','A partial original, an unavailable predecessor or an unsupported namespace cannot be silently replaced by a guessed source. The reader should see what the evidence actually supports. A deterministic method can reconstruct supported attribution; it cannot manufacture missing historical facts.']
],['/learn/receipts/','/learn/reserve-and-settlement/','/ledger/']),
page('memory-crystals','History','Memory Crystals','Retain loaded Ledger evidence and original proof sources in a local, independently reopenable record.','Keep the record with its evidence.','receipt',[
 ['A source-carried record','A Memory Crystal retains the result and the original evidence included in its declared scope. It is useful because the source can travel with the saved object, instead of leaving only a screenshot or a link to a changing page.'],
 ['Save what is already loaded','The public Ledger save uses the records and proofs already held in that view. Saving does not need another inventory fetch simply to reconstruct the visible result. The export should state its actual included scope rather than claim unseen history.'],
 ['Local save and hosted retention','A local Ledger export is a file saved on your device. It does not by itself mean a cloud upload, remote admission or permanent hosting. A hosted byte service has its own availability, admission and retention evidence; a reachable URL cannot establish those properties.'],
 ['Reopen and inspect','Keep the original file intact and use a matching supported reader. A reader checks the carried bytes, source relationships and relevant schema. A beautiful cover image is presentation; integrity and continuity come from the evidence inside the original.'],
 ['Know what is retained','Private account identity, public Ledger evidence and an explicitly shared transaction have different disclosure scopes. Save and share only the intended source. An export is not spend authority, a substitute for device-bound Note custody or a promise that every private account event is included.']
],['/ledger/','/learn/receipts/','/verify/']),
page('time-and-ordering','History','Time and ordering','Understand local dates, Kai-Klok KKSv1, exact pulse coordinates and the separate requirement for exclusive consumption.','A familiar time. An exact coordinate underneath.','timing',[
 ['Local time first','Familiar dates and local time help you recognize an event. The retained source carries the coordinate required by its protocol. A timezone changes a human-readable presentation; it does not change the identity of the signed action.'],
 ['Kai-Klok KKSv1','The clock expresses beat, step and pulse with phase, day, week and month details. The exact ☤KAI pulse provides a coordinate for supported calculations and source comparison. Read the current moment’s description as a contextual explanation of the clock’s system, not a medical or investment claim.'],
 ['An event and its display','A transfer’s supported pulse can be used with held deterministic valuation inputs to reconstruct its value at that moment. The current pulse supports a current calculation. Neither should silently replace the other in a receipt or historical chart.'],
 ['Ordering is not consumption','A signed timestamp can locate a claim in the protocol’s time system. It cannot alone prove that a copied credential never authorized a conflicting claim. Once-only consumption needs the applicable connected state or qualified irreversible protected custody.'],
 ['History needs the right origin','Assets enter historical aggregates at their actual supported seal or opening coordinates. A build time, current fetch or later pricing snapshot is not the source’s creation time. Unknown timing must remain unknown rather than becoming an invented event.']
],['/learn/price-history/','/learn/notes/','/standards/']),
page('standards','Standards','Proof-native economic standards','Inspect the applicable contracts, evidence requirements, assessment scopes and failure conditions for proof-native economic continuity.','Defined requirements. Demonstrated results.','conformance',[
 ['A stated scope','Conformance evaluates an implementation against an identified contract and version. State the exact capability being assessed: source reading, ownership continuity, connected execution, qualified local custody or another defined profile. No result silently expands to every capability an institution offers.'],
 ['Normative sources','Use the pinned Receiz schemas, registry, primitive contracts and matching implementation as the source of exact protocol requirements. These pages explain the integration; they do not invent a competing issuer or amend the pinned financial rules through marketing language.'],
 ['Evidence before a verdict','A conforming result requires the complete applicable checks and required evidence. A reproduced failure is nonconforming within that assessed scope. Missing evidence is not assessed or not demonstrated. Out of scope means the capability was excluded, not that an institution declined adoption.'],
 ['Adversarial cases','Assessment includes altered bytes, forged participants, changed amount or split, stale predecessors, replay, rollback, concurrent claims and interrupted execution. Test unknown namespaces and incomplete lineage too. A happy-path demo cannot replace evidence that these cases are refused.'],
 ['Device custody','Continuous offline creation and onward transfer require non-exportable authority and irreversible, independently verifiable consumption bound to the exact predecessor, value and recipient. Writable browser storage, a derivation key, locks or a timestamp cannot establish that property alone.'],
 ['Independent receiving','An independent receiver needs exact-byte sources, matching schemas, a stated trust policy and a reproducible verification result. Reference tests use declared fixtures. They do not automatically qualify a physical device, production funds or a separately deployed service.'],
 ['The same rule for this implementation','Bankeiz’s release evidence must state what passed, what failed and what remains unassessed. A protocol-pinned report does not grant spend authority, legal recognition or universal certification. Publish corrections and rerun affected checks when implementation or policy changes.']
],['/conformance/','/institutions/','/schemas/'],{path:'/standards/'}),
page('institutions','Standards','For institutions','Plan an evidence-preserving integration across identity, funds, assets, custody, receiving and independent verification.','Integrate the capability. Demonstrate the result.','conformance',[
 ['Choose your role','An institution can be a source issuer, custodian, application operator, receiver or verifier. Each role needs an explicit capability and trust boundary. Begin with what the integration will actually do, the supported assets and value, and who is authorized to act.'],
 ['Reuse the existing authority','Integrate through the supported Receiz SDK, MCP or AI Skills as appropriate. Keep financial admission, identity authority and once-only execution in their original contracts. A separate label or endpoint that bypasses those rules does not establish continuity.'],
 ['Receiving and reconciliation','A receiver must inspect source integrity, ownership, recipient binding, exact units and predecessor relationships. Connected credit must be once-only and recoverable after a lost response. Retained offline receipt must stay distinct from confirmed spendable account credit.'],
 ['Custody responsibilities','Device manufacturers supply protected authority and irreversible state. Operating systems preserve it across crashes and restoration. Browser vendors expose the bound operation safely. Integrators admit the exact evidence and qualify it under the supported trust policy. No single advertised feature substitutes for the complete path.'],
 ['Prepare evidence artifacts','Record versions, build identity, configuration scope, fixtures, expected refusals and actual results. Retain original sources and reproducible commands. Financial conservation, interrupted operations and physical-device behavior need evidence appropriate to the deployed implementation, beyond pure reference tests.'],
 ['Assess and maintain','Use the public Conformance workspace and independent receiver materials. Publish exclusions honestly. Reassess after changing custody, storage, trust policy, recovery or financial execution. Conformance is a maintained technical result rather than an institution-wide badge.']
],['/standards/','/developers/','/conformance/'],{path:'/institutions/'}),
page('developers','Standards','For developers','Build on Receiz SDK, MCP and AI Skills with exact sources, existing authority and independently testable boundaries.','Build the experience. Preserve the protocol.','verification',[
 ['Accept a payment','Start with a link or copied button for the smallest integration. For a custom application, the payment reference includes a typed SDK example: create checkout from your trusted order, display the existing secure card form, then confirm the exact recipient, amount and recorded credit before delivery. Keep the returned session against the order so closing a tab does not create a second payment. The Get paid guide explains setup without code; the implementation reference shows the complete developer lifecycle.'],
 ['Start from the pinned version','This reference implementation uses Receiz v129 SDK, MCP and AI Skills. Read the corresponding schemas and primitive contracts before adding an action. A package version identifies source compatibility; it does not prove the selected live host has deployed every capability.'],
 ['Go beyond checkout','Compose account payments, current Notes, asset ownership and original receipts through their existing Receiz contracts. The payment reference maps subscriptions, refunds, tax, shipping, discounts, inventory, fulfillment and payouts to the coordinated commerce surfaces, and identifies the scopes and host support each requires. MCP and AI Skills provide their supported agent workflows. Start with one operation and add capabilities without building a second payment ledger or granting an agent blanket financial authority.'],
 ['Use the right surface','The SDK composes application operations. MCP and AI Skills expose their supported tools and workflows. They do not imply interchangeable permissions or license an agent to perform arbitrary financial actions. Keep the account identity, granted scope and action authorization explicit.'],
 ['Retain exact sources','Keep original bytes, identity bindings, predecessor references and signed results. A projection is for presentation. It must not become a new authority simply because it is easier to read than the proof. Unknown or unsupported data fails within its declared boundary.'],
 ['Recover the same operation','Persist the exact attempted action before consequential submission. After an uncertain response, query or resume that operation before considering another. Bind recipient, amount, quote, funding split and identity across recovery. Never clear unknown financial state to make a retry appear fresh.'],
 ['Fast presentation, deliberate execution','Reuse held observations and deduplicated readers for immediate display. Synchronize in the background where supported. Avoid extra polling or fetching a second copy of already retained evidence. Consequential execution still validates current authority and state; latency goals cannot weaken those checks.'],
 ['Test the boundary','Use reference fixtures for pure verification, adapter tests for source selection and execution, and real devices for physical custody claims. Publish negative results and deployment limits. The source archive, schemas and institution receiver provide concrete starting points for independent inspection.']
],['/learn/get-paid/','/schemas/','/conformance/','/institutions/'],{path:'/developers/',resources:[['Payment quick start and integration reference','https://github.com/kojibai/reality-grade-banking/blob/main/institution/accept-payments.md'],['Typed checkout and confirmation example','https://github.com/kojibai/reality-grade-banking/blob/main/institution/examples/merchant-checkout.ts']]}),
page('security','Standards','Security and authority','Understand identity custody, exact action approval, proof verification, replay protection and honest recovery boundaries.','Authority stays explicit. Evidence stays connected.','verification',[
 ['Identity custody','The Identity Record carries signing custody. The application uses usable signing material on the device and retains protected local records. Protect the original Record, its required phrase and the unlocked device. Encryption at rest does not make an unlocked, compromised runtime trustworthy.'],
 ['Exact authorization','Account access grants its defined read and communication scope. A payment, purchase, publication or custody action needs the authorization appropriate to that operation. A public username, a suggested assistant action or an on-screen balance cannot expand those permissions.'],
 ['Verify the source','Check original bytes, signatures, schema, participants, value and predecessor relationships. Presentation metadata supports discovery but cannot override a failed original. An unknown proof format must not receive a universal verified label.'],
 ['Replay and rollback','Once-only connected consumption and qualified offline protected state address different environments. A copied file, local clock or synced passkey cannot establish irreversible consumption alone. Continuous offline custody needs the actual protected operation and admissible evidence, not a weaker substitution.'],
 ['Recovery without invention','Lost replies leave uncertain outcomes. Retain the exact attempt and recover its existing result. Never infer success from a spinner ending or failure from a timeout. Keep unknown financial state intact until its supported recovery determines the outcome.'],
 ['Assessment scope','Reference checks establish the properties they actually exercise. They do not prove production configuration, device security or every external claim. Publish the exact version and assessed capability. Treat unassessed behavior as unassessed rather than implying certification.']
],['/learn/signing-key/','/learn/account-access/','/standards/']),
page('releases','Standards','Releases and qualification','Inspect the 2.0.0 release source, implementation evidence and capability-specific production and device qualification records.','A release is a demonstrated scope.','conformance',[
 ['Version 2.0.0','Reality-Grade Banking 2.0.0 brings public profiles, complete asset creation, account-wide investments, connected payment journeys and richer original media to the open architecture. Its versioned release record describes what ships and the exact verification scope. The release records identify the exact source, compatibility and assessed scope.'],
 ['Version 1.0.0','Reality-Grade Banking 1.0.0 was published on October 20, 2026 from release commit 2231301. It brings the open banking architecture, Bankeiz reference application, receiving materials and verification evidence together. The release records identify the exact source and capability-specific assessment scope.'],
 ['Implemented scope','The reference composition includes account access, payments, public discovery, source-carried history, messages and connected Note creation across automatic Reserve, Settlement and composite funding. Availability depends on the selected host capabilities, registered integration and supported Receiz contracts.'],
 ['Reference evidence','Repository verification records describe the commands, fixtures and exact scope used. Tests cover supported conservation, source bindings, replay refusal and recovery cases. Their synthetic identities and isolated data are not production financial qualification.'],
 ['Required live qualification','Verify the deployed host and application versions, funded Reserve and Settlement creation, mixed funding, interrupted issuance, recipient-bound receipt, once-only credit and recovery. Test the intended iPhone/PWA path. Qualified continuous offline custody additionally needs real protected-device evidence.'],
 ['Publish complete results','A release record should identify the exact commit, build, protocols, assessed capabilities, exclusions and reproducible evidence. Keep failed and unassessed cases visible. A hosted storage service’s separate availability or admission is not established by application tests.'],
 ['Independent inspection','Use the public source archive, schema catalog, institution receiver and Conformance workspace to reproduce the supported checks. Changes to trust policy, custody, recovery or financial execution require a new assessment of their affected scope.']
],['/conformance/','/standards/','/developers/'],{path:'/releases/',resources:[['Version 2.0.0 — full release notes','https://github.com/kojibai/reality-grade-banking/blob/main/docs/releases/2.0.0.md'],['Release history and qualification','https://github.com/kojibai/reality-grade-banking/blob/main/docs/releases/README.md']]}),
page('glossary','Standards','Glossary','Plain definitions of proof objects, balance, Reserve, Settlement, custody, valuation, attribution and conformance.','Familiar words. Precise meanings.','verification',[
 ['Proof object','An original structured source carrying a claim and the evidence its format supports. Integrity, authorship, ownership and external truth are distinct questions. A proof object can be an asset without every record being money or executable backing.'],
 ['Balance, Reserve and Settlement','A balance presents the supported value in an account. Reserve records proof-backed funds. Settlement records proof-native value in exact Phi units with a supported dollar presentation. Automatic funding preserves their distinctions beneath one amount.'],
 ['Note and custody','A funded Note carries its original source and applicable authority. Receiving proof, holding custody, confirmed account credit and permission for onward spending are different states. A preview or copied image establishes none of them on its own.'],
 ['Valuation and price','A valuation is a supported calculation at a moment. A transaction price is an amount established by an actual transaction. Market capitalization aggregates defined valuations; it is not cash backing, liquidity or realized economic output.'],
 ['Causal history and FIFO','Causal history connects a record to its supporting predecessors. Calculated FIFO attribution assigns the oldest available supported funding basis first. It explains pooled funds without claiming the original transfer recorded that individual allocation.'],
 ['Conformance','A result against an identified contract, version and capability. Conforming requires the applicable evidence. Nonconforming requires an observed failure. Not assessed means evidence or assessment is absent. Out of scope identifies an excluded capability.'],
 ['Moment and pulse','Local time is a familiar presentation of an event. Kai-Klok KKSv1 provides the protocol coordinate used by supported source and valuation rules. An exact pulse does not by itself prove exclusive consumption or prevent a copied authority from signing twice.']
],['/learn/questions/','/learn/proof-native-economy/','/standards/']),
page('questions','Standards','Questions and answers','Practical answers about opening an account, paying, receiving Notes, asset value, originals and conformance.','The details you need. When you need them.','journey',[
 ['Do I need to choose a rail?','No. Ordinary payments and Notes use one amount, taking available Reserve first and Settlement for the remainder. The original proof preserves the composition. Technical details remain available when you need to inspect the funding.'],
 ['Can I receive a Note offline?','A completed recipient-bound account Note can be verified and saved offline without custody enrollment. Its deposit reconciles when connected before the amount can fund a payment or another Note. Continuous creation of new spend authority fully offline requires qualified protected custody and prepared resources.'],
 ['Does a normal connected Note need Face ID conformance?','Connected creation uses Receiz’s connected authorization. It does not ask the user to qualify the device’s offline custody. Identity unlocking or another device permission is a separate action; the optional device diagnostic is not part of ordinary receipt.'],
 ['Does an asset’s value mean I can withdraw that amount?','No. A supported valuation is a calculation. Cash proceeds, redemption, backing and liquidity depend on actual rights and executable transactions. A chart cannot independently establish those facts.'],
 ['What should I save?','Keep original Identity Records privately and preserve original assets, Notes and receipts that matter to you. Screenshots and converted images can lose their structured evidence. A backup of identity access does not clone protected device-bound custody.'],
 ['What if a payment or Note stops halfway?','Resume the retained attempt. A lost reply leaves an uncertain outcome; it does not prove the operation failed. The application checks the existing result before submitting a different action, protecting against duplicate execution.'],
 ['How can an institution assess it?','Declare the exact version and capability, inspect the pinned contracts, run the applicable negative and positive checks, and publish complete evidence. The public standard and institution guide identify responsibilities and the limits of reference and device assessments.']
],['/learn/notes/','/learn/your-account/','/institutions/']),
];

export const learningGroups=['For you','Banking','Assets','Markets','History','Standards'];
export const learningPath=page=>page.path??`/learn/${page.slug}/`;
export const assetCategories=[
 ['Music','music','Audio works, recordings and music sources. Inspect the authored original, its ownership and the rights actually carried.'],
 ['Images','images','Photography, visual art and image-based originals. Follow each image to its claim, author and supported ownership history.'],
 ['Videos','videos','Moving-image originals and their carried sources. Review the work, its context and the rights defined by the object.'],
 ['Books','books','Book-length works with their original publication evidence. Access, ownership and distribution rights remain defined by each source.'],
 ['Essays','essays','Long-form writing and authored arguments. Read the source and inspect the moment, attribution and history it records.'],
 ['Moments','moments','Sealed moments with an explicit claim and context. Examine what was recorded and the evidence the source actually establishes.'],
 ['Collectibles','collectibles','Sports cards, signal cards and other collectible originals. Inspect supported live value, opening coordinates and ownership history.'],
 ['Documents','documents','Document sources and their inspectable records. Check authorship, integrity, rights and the evidence carried by the original.'],
].map(([label,slug,description])=>({label,slug,description,path:`/explore/${slug}/`}));
